class Pedido {
  final String id;
  final String? destino; // el ? dice: puede ser null
  Pedido(this.id, [this.destino]);
}

String describir(Pedido p) {
  // El compilador obliga a contemplar el null
  return '${p.id} -> ${p.destino ?? "sin destino"}';
}

Future<int> contarCajas() async {
  await Future.delayed(Duration(milliseconds: 50));
  return 42;
}

void main() async {
  print(describir(Pedido('A1', 'Rosario')));
  print(describir(Pedido('A2')));
  print('cajas: ${await contarCajas()}');
  final lista = [3, 1, 2]..sort();
  print(lista);
}

