import 'dart:isolate';

int contador = 0;

void main() async {
  contador = 1;
  final visto = await Isolate.run(() {
    final alEntrar = contador;
    contador += 100;
    return 'otro isolate: al entrar vio $alEntrar, ahora tiene $contador';
  });
  print(visto);
  print('main: contador = $contador');
}

class _PantallaState extends State<Pantalla> {
  int cajas = 0;
  @override
  Widget build(BuildContext context) {
    return Scaffold(
      body: Center(
        child: Column(
          mainAxisSize: MainAxisSize.min,
          children: [
            Text('Cajas cargadas: $cajas'),
            const SizedBox(height: 16),
            FilledButton(
              onPressed: () => setState(() => cajas++),
              child: const Text('Sumar una caja'),
            ),
          ],
        ),
      ),
    );
  }
}

